import { MouseEvent, useEffect, useMemo, useState } from "react";
import {
  AppBar,
  Backdrop,
  Box,
  Button,
  CircularProgress,
  Divider,
  Drawer,
  IconButton,
  List,
  ListItemButton,
  ListItemText,
  Menu,
  MenuItem,
  Stack,
  Toolbar,
  Typography,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import KeyboardArrowDownIcon from "@mui/icons-material/KeyboardArrowDown";
import MenuIcon from "@mui/icons-material/Menu";
import api, { mediaUrl } from "../services/api";
import type { HeaderData, HeaderResponse, MenuItem as NavItem, MenuLink } from "../types/header";

const NAV_COLOR = "#17224d";
const NAV_HOVER = "#759ae1";

export default function Header() {
  const [header, setHeader] = useState<HeaderData | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [pageLoading, setPageLoading] = useState(false);
  const [courseAnchor, setCourseAnchor] = useState<HTMLElement | null>(null);
  const [mobileCoursesOpen, setMobileCoursesOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;

    api
      .get<HeaderResponse>("/header", {
        params: {
          "populate[logo]": true,
          "populate[menuItems][populate]": "children",
        },
      })
      .then((payload) => {
        if (!cancelled) setHeader(payload.data || null);
      })
      .catch(() => {
        if (!cancelled) setHeader(null);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  const menuItems = useMemo(() => header?.menuItems || [], [header]);
  const courseItem = useMemo(
    () => menuItems.find((item) => item.children?.length) || null,
    [menuItems]
  );

  const openHeaderUrl = (url?: string, event?: MouseEvent) => {
    if (!url) return;
    event?.preventDefault();
    setPageLoading(true);
    setCourseAnchor(null);
    setDrawerOpen(false);
    window.open(url, "_blank", "noopener,noreferrer");
    window.setTimeout(() => setPageLoading(false), 800);
  };

  const logoSrc = mediaUrl(header?.logo);
  const logoAlt = header?.logo?.alternativeText || header?.logoAlt || "DocTutorials";

  const renderLogo = (height?: number) => (
    <Box
      component="a"
      href="/"
      sx={{ display: "inline-flex", alignItems: "center", lineHeight: 0 }}
    >
      {logoSrc ? (
        <Box
          component="img"
          src={logoSrc}
          alt={logoAlt}
          sx={{
            width: height ? 56 : { xs: 56, md: 70, tv: 84 },
            height: height || { xs: 40, md: 52, tv: 62 },
            objectFit: "contain",
          }}
        />
      ) : null}
    </Box>
  );

  const navButtonSx = {
    color: NAV_COLOR,
    fontSize: { md: 13, lg: 15, tv: 17 },
    fontWeight: 500,
    letterSpacing: "0.3px",
    textTransform: "none",
    px: { md: 1, lg: 1.5, tv: 2 },
    "&:hover": { color: NAV_HOVER, backgroundColor: "transparent" },
  };

  const loginButton = (
    <Button
      variant="contained"
      disableElevation
      onClick={(event) => openHeaderUrl(header?.loginUrl, event)}
      sx={{
        minWidth: 136,
        height: 35,
        borderRadius: "6px",
        backgroundColor: NAV_HOVER,
        fontWeight: 700,
        fontSize: 14,
        textTransform: "none",
        "&:hover": { backgroundColor: "#5f86d4" },
      }}
    >
      {header?.loginLabel || "Login/Signup"}
    </Button>
  );

  const renderDesktopItem = (item: NavItem) => {
    const hasChildren = Boolean(item.children?.length);
    if (!hasChildren) {
      return (
        <Button key={item.id || item.label} sx={navButtonSx} onClick={(event) => openHeaderUrl(item.url, event)}>
          {item.label}
        </Button>
      );
    }

    return (
      <Button
        key={item.id || item.label}
        sx={{
          ...navButtonSx,
          border: "0.75px solid #cdcdcd",
          borderRadius: "5px",
          px: 2,
        }}
        endIcon={<KeyboardArrowDownIcon />}
        onClick={(event) => setCourseAnchor(event.currentTarget)}
      >
        {item.label}
      </Button>
    );
  };

  return (
    <>
      <AppBar
        position="fixed"
        elevation={0}
        sx={{
          backgroundColor: "rgba(255,255,255,0.85)",
          backdropFilter: "blur(12.5px)",
          boxShadow: "0 4px 30px 0 rgba(0,0,0,0.08)",
          color: NAV_COLOR,
        }}
      >
        <Toolbar
          sx={{
            maxWidth: { xs: "100%", lg: 1360, tv: 1680 },
            width: "100%",
            mx: "auto",
            px: { xs: 1.5, sm: 2, md: 4, lg: 5, tv: 8 },
            minHeight: { xs: 56, sm: 64, md: 72, tv: 84 },
            justifyContent: "space-between",
            gap: 2,
          }}
        >
          <Stack direction="row" alignItems="center" spacing={1}>
            <IconButton
              color="inherit"
              onClick={() => setDrawerOpen(true)}
              sx={{ display: { xs: "inline-flex", md: "none" } }}
              aria-label="Open menu"
            >
              <MenuIcon />
            </IconButton>
            {renderLogo()}
          </Stack>

          {courseItem ? (
            <Button
              variant="outlined"
              size="small"
              endIcon={<KeyboardArrowDownIcon />}
              onClick={(event) => setCourseAnchor(event.currentTarget)}
              sx={{
                display: { xs: "inline-flex", md: "none" },
                color: NAV_COLOR,
                borderColor: "#cdcdcd",
                textTransform: "none",
                fontSize: 12,
              }}
            >
              {courseItem.label || "Courses"}
            </Button>
          ) : null}

          <Stack direction="row" alignItems="center" spacing={0.5} sx={{ display: { xs: "none", md: "flex" } }}>
            {menuItems.map(renderDesktopItem)}
          </Stack>

          <Box sx={{ display: { xs: "none", md: "block" } }}>{header?.loginUrl ? loginButton : null}</Box>
        </Toolbar>
      </AppBar>
      <Toolbar sx={{ minHeight: { xs: 56, sm: 64, md: 72, tv: 84 } }} />

      <Menu
        anchorEl={courseAnchor}
        open={Boolean(courseAnchor)}
        onClose={() => setCourseAnchor(null)}
        slotProps={{
          paper: {
            sx: {
              mt: 1,
              minWidth: 180,
              borderRadius: "8px",
              boxShadow: "4px 4px 20px 0 rgba(0,0,0,0.25)",
            },
          },
        }}
      >
        {(courseItem?.children || []).map((child: MenuLink) => (
          <MenuItem key={child.id || child.url} onClick={(event) => openHeaderUrl(child.url, event)}>
            {child.label}
          </MenuItem>
        ))}
      </Menu>

      <Drawer
        anchor="left"
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        PaperProps={{
          sx: { width: "80%", maxWidth: 320, backgroundColor: "#edf2fb" },
        }}
      >
        <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ p: 2, borderBottom: "1px solid #cdcdcd" }}>
          {renderLogo(42)}
          <IconButton onClick={() => setDrawerOpen(false)} aria-label="Close menu">
            <CloseIcon />
          </IconButton>
        </Stack>

        {header?.loginUrl ? (
          <Box sx={{ p: 2, borderBottom: "1px solid #cdcdcd" }}>{loginButton}</Box>
        ) : null}

        <List>
          {menuItems.map((item) => {
            const hasChildren = Boolean(item.children?.length);
            if (!hasChildren) {
              return (
                <ListItemButton key={item.id || item.label} onClick={(event) => openHeaderUrl(item.url, event)}>
                  <ListItemText primary={item.label} />
                </ListItemButton>
              );
            }

            return (
              <Box key={item.id || item.label}>
                <ListItemButton onClick={() => setMobileCoursesOpen((open) => !open)}>
                  <ListItemText primary={item.label} />
                  <KeyboardArrowDownIcon />
                </ListItemButton>
                {mobileCoursesOpen
                  ? item.children?.map((child) => (
                      <ListItemButton
                        key={child.id || child.url}
                        sx={{ pl: 4 }}
                        onClick={(event) => openHeaderUrl(child.url, event)}
                      >
                        <ListItemText primary={child.label} />
                      </ListItemButton>
                    ))
                  : null}
              </Box>
            );
          })}
        </List>
        <Divider />
      </Drawer>

      <Backdrop open={pageLoading} sx={{ zIndex: 20000, color: "#fff", backgroundColor: "rgba(255,255,255,0.72)" }}>
        <CircularProgress sx={{ color: NAV_HOVER }} />
        <Typography sx={{ position: "absolute", bottom: 40, color: NAV_COLOR }}>Opening...</Typography>
      </Backdrop>
    </>
  );
}
